//! Independent logical fixtures from the approved wire formulas, not the production Encoder.
pub const Vector = struct { bytes: []const u8, chain: [32]u8 };

fn nibble(comptime c: u8) u8 {
    return switch (c) {
        '0'...'9' => c - '0',
        'a'...'f' => c - 'a' + 10,
        else => @compileError("invalid fixture hex"),
    };
}

fn decode(comptime hex: []const u8) [hex.len / 2]u8 {
    if (hex.len % 2 != 0) @compileError("odd fixture hex length");
    var out: [hex.len / 2]u8 = undefined;
    for (&out, 0..) |*byte, index| byte.* = nibble(hex[index * 2]) * 16 + nibble(hex[index * 2 + 1]);
    return out;
}

